(text as String).toLowerCase().split(/[^\p{L}\p{N}]+/).each { w -> if (w) v[Math.abs(w.hashCode() % 64)] += 1.0 }
embedding = v.toList()

actions.script:
import groovy.json.JsonOutput
import groovy.json.JsonSlurper
String url, body
if (embedProvider == 'openai') {
    url = 'https://api.openai.com/v1/embeddings'
    body = JsonOutput.toJson([model: model, input: text])
} else {
    url = "https://generativelanguage.googleapis.com/v1beta/models/${model}:embedContent?key=${apiKey}"
    body = JsonOutput.toJson([content: [parts: [[text: text]]]])
}
HttpURLConnection conn = (HttpURLConnection) new URL(url).openConnection()
conn.setRequestMethod('POST')
conn.setRequestProperty('Content-Type', 'application/json')
if (embedProvider == 'openai') conn.setRequestProperty('Authorization', "Bearer ${apiKey}")
conn.setConnectTimeout(15000); conn.setReadTimeout(30000)
conn.doOutput = true
conn.outputStream.withWriter('UTF-8') { it.write(body) }
int code = conn.responseCode
String resp = ((code >= 200 && code < 300) ? conn.inputStream : conn.errorStream)?.getText('UTF-8')
if (code < 200 || code >= 300) {
    ec.message.addError("Embedding request failed (${embedProvider}, ${code}): ${resp?.take(300)}")
    return
}
def parsed = new JsonSlurper().parseText(resp)
embedding = (embedProvider == 'openai') ? parsed?.data?.getAt(0)?.embedding : parsed?.embedding?.values
if (embedding == null) ec.message.addError("No embedding in response: ${resp?.take(200)}")

String t = (text as String).trim()
int size = 2000, overlap = 200
chunks = []
if (t.length() <= size) { chunks = [t] }
else {
    int i = 0
    while (i < t.length()) {
        int end = Math.min(i + size, t.length())
        if (end < t.length()) {
            int ws = t.lastIndexOf(' ', end)
            if (ws > i + (size/2 as int)) end = ws
        }
        chunks.add(t.substring(i, end).trim())
        if (end >= t.length()) break
        i = end - overlap
        if (i < 0) i = 0
    }
}
chunks = chunks.findAll { it }

import org.moqui.resource.ResourceReference

String rootLoc = wikiSpace.rootPageLocation
String bundleDirLoc = rootLoc.endsWith('.md') ? rootLoc.substring(0, rootLoc.length() - 3) : rootLoc
ResourceReference bundleDir = ec.resource.getLocationReference(bundleDirLoc)

List files = []
def walk
walk = { ResourceReference dir, String rel ->
    for (child in dir.getDirectoryEntries()) {
        String childRel = rel ? rel + '/' + child.fileName : child.fileName
        if (child.isDirectory()) { walk(child, childRel) }
        else if (child.fileName.endsWith('.md') &&
                child.fileName != 'index.md' && child.fileName != 'log.md') {
            files.add([ref: child, rel: childRel])
        }
    }
}
walk(bundleDir, '')

def yaml = new org.yaml.snakeyaml.Yaml()
int docs = 0
int chunksTotal = 0
for (f in files) {
    if (pathPrefix && !f.rel.startsWith(pathPrefix)) continue
    String text = f.ref.getText()
    if (!text) continue
    Map fm = [:]
    String body = text
    def m = (text =~ /(?s)\A---\n(.*?)\n---\n?(.*)/)
    if (m.matches()) {
        try { fm = (yaml.load(m.group(1)) as Map) ?: [:] } catch (Exception e) { fm = [:] }
        body = m.group(2)
    }
    String title = (fm.title ?: f.rel) as String
    String metadataJson = groovy.json.JsonOutput.toJson(fm)
    def existing = ec.entity.find('moqui.adk.AdkKnowledgeDoc')
            .condition('ownerPartyId', ownerPartyId).condition('sourceType', 'okf')
            .condition('sourceId', f.rel).one()
    Map out
    if (existing != null) {
        existing.title = title
        existing.mimeType = 'text/markdown'
        existing.metadataJson = metadataJson
        existing.update()
        out = ec.service.sync().name('AdkKnowledgeServices.update#AdkKnowledge')
                .parameters([adkKnowledgeDocId: existing.adkKnowledgeDocId,
                             ownerPartyId: ownerPartyId, text: body]).call()
    } else {
        out = ec.service.sync().name('AdkKnowledgeServices.ingest#AdkKnowledge')
                .parameters([ownerPartyId: ownerPartyId, title: title, text: body,
                             sourceType: 'okf', sourceId: f.rel, mimeType: 'text/markdown',
                             metadataJson: metadataJson]).call()
    }
    docs++
    chunksTotal += (out?.chunkCount ?: 0) as int
}
docCount = docs
chunkCount = chunksTotal
ec.logger.info("OKF ingest: ${docs} concepts, ${chunksTotal} chunks (space ${wikiSpaceId}, owner ${ownerPartyId})")

import groovy.json.JsonSlurper
def q = qEmbed.embedding?.collect { (it as Number).doubleValue() }
results = []
if (q == null) return
double qNorm = Math.sqrt(q.sum { it * it } as double)
def slurper = new JsonSlurper()
def scored = []
for (chunk in chunkList) {
    def v = slurper.parseText(chunk.embeddingJson as String)?.collect { (it as Number).doubleValue() }
    if (v == null || v.size() != q.size()) continue
    double dot = 0.0, vNorm = 0.0
    for (int i = 0; i < q.size(); i++) { dot += q[i] * v[i]; vNorm += v[i] * v[i] }
    vNorm = Math.sqrt(vNorm)
    double score = (qNorm == 0 || vNorm == 0) ? 0.0 : dot / (qNorm * vNorm)
    scored.add([chunk: chunk, score: score])
}
scored.sort { -it.score }
def docTitles = [:]
results = scored.take(limit as int).collect { s ->
    def c = s.chunk
    String title = docTitles[c.adkKnowledgeDocId]
    if (title == null) {
        def d = ec.entity.find('moqui.adk.AdkKnowledgeDoc')
                .condition('adkKnowledgeDocId', c.adkKnowledgeDocId).one()
        title = d?.title ?: ''
        docTitles[c.adkKnowledgeDocId] = title
    }
    [text: c.text, title: title, sourceType: null, score: s.score]
}

import groovy.json.JsonOutput
import java.util.zip.ZipInputStream

String ownerPartyId = job.ownerPartyId
List skipped = []
int created = 0, updated = 0, processed = 0
String fatal = null
def progress = { Map extra ->
    ec.service.sync().name('AdkKnowledgeServices.update#AdkKnowledgeImportStatus')
        .parameters([adkKnowledgeImportId: adkKnowledgeImportId, processedCount: processed,
                     createdCount: created, updatedCount: updated, skippedCount: skipped.size(),
                     skippedJson: JsonOutput.toJson(skipped)] + extra).call()
}
// Run one document service in its own transaction; its error message, or null
def runDoc = { String name, Map params ->
    ec.service.sync().name(name).parameters(params).requireNewTransaction(true).call()
    if (!ec.message.hasError()) return null
    String msg = ec.message.errorsString
    ec.message.clearErrors()
    return msg
}
// missing key or used-up allowance fails every later file too: stop the load
def isFatal = { String msg -> msg.contains('API key') || msg.contains('allowance') || msg.contains('token limit') }

try {
    if (job.jobType == 'REINDEX') {
        def modelOut = ec.service.sync().name('AdkKnowledgeServices.get#TenantEmbedKey')
            .parameters([ownerPartyId: ownerPartyId]).call()
        String currentModel = ec.service.sync().name('AdkKnowledgeServices.get#EmbedModel')
            .parameters([embedProvider: modelOut.embedProvider]).call().model
        List staleDocIds = ec.entity.find('moqui.adk.AdkKnowledgeChunkSummary')
            .condition('ownerPartyId', ownerPartyId)
            .selectFields(['adkKnowledgeDocId', 'embeddingModel', 'chunkCount']).list()
            .findAll { it.embeddingModel != currentModel }*.adkKnowledgeDocId.unique()
        progress([fileCount: staleDocIds.size()])
        for (String docId in staleDocIds) {
            def doc = ec.entity.find('moqui.adk.AdkKnowledgeDoc').condition('adkKnowledgeDocId', docId).one()
            // chunks overlap ~200 characters: drop the repeated start of each next chunk
            StringBuilder sb = new StringBuilder()
            for (ch in ec.entity.find('moqui.adk.AdkKnowledgeChunk').condition('adkKnowledgeDocId', docId)
                    .selectFields(['seq', 'text']).orderBy('seq').list()) {
                String t = ch.text ?: ''
                int k = Math.min(300, Math.min(t.length(), sb.length()))
                while (k >= 20 && !sb.toString().endsWith(t.substring(0, k))) k--
                if (k >= 20) sb.append(t.substring(k)) else { if (sb.length()) sb.append('\n'); sb.append(t) }
            }
            String msg = sb.toString().trim() ? runDoc('AdkKnowledgeServices.index#AdkKnowledgeChunks',
                [adkKnowledgeDocId: docId, ownerPartyId: ownerPartyId, text: sb.toString()]) : 'no text'
            if (msg && isFatal(msg)) { fatal = msg; break }
            if (msg) skipped.add([path: doc?.title ?: docId, reason: msg])
            else updated++
            processed++
            progress([:])
        }
    } else {
        def CourseAiUtil = ec.resource.script('component://growerp/service/course/CourseAiUtil.groovy', null)
        Set textExt = ['txt', 'md', 'markdown', 'csv', 'json', 'log', 'text'] as Set
        // of the stored text: pdf and docx are stored as their extracted plain text
        Map mimeTypes = [md: 'text/markdown', markdown: 'text/markdown', csv: 'text/csv',
                         json: 'application/json']
        String fileName = job.fileName ?: 'upload.zip'
        String zipBase = fileName.replaceAll(/(?i)\.zip$/, '')
        List files = []
        new ZipInputStream(new ByteArrayInputStream(Base64.getMimeDecoder().decode(job.zipData as String))).withCloseable { zin ->
            def entry
            while ((entry = zin.getNextEntry()) != null) {
                String path = entry.getName().replace('\\', '/')
                String base = path.tokenize('/') ? path.tokenize('/').last() : path
                if (entry.isDirectory() || path.startsWith('__MACOSX/') || base.startsWith('.')) continue
                String ext = base.contains('.') ? base.substring(base.lastIndexOf('.') + 1).toLowerCase() : ''
                if (!(ext in textExt) && ext != 'pdf' && ext != 'docx') {
                    skipped.add([path: path, reason: 'unsupported file type']); continue
                }
                files.add([path: path, ext: ext, bytes: zin.readAllBytes()])
            }
        }
        progress([fileCount: files.size()])
        for (Map f in files) {
            String text = null
            String msg = null
            try {
                text = f.ext in textExt ? new String(f.bytes as byte[], 'UTF-8') :
                    CourseAiUtil.extractText(ec, f.path as String, f.bytes as byte[])
            } catch (Exception e) { msg = "could not read: ${e.message}" }
            if (ec.message.hasError()) { msg = ec.message.errorsString; ec.message.clearErrors() }
            if (!msg && !text?.trim()) msg = 'no text'
            if (!msg) {
                String path = f.path
                String title = path.contains('.') ? path.substring(0, path.lastIndexOf('.')) : path
                String folder = path.contains('/') ? path.substring(0, path.lastIndexOf('/')) : ''
                String sourceId = zipBase + '/' + path
                def existing = ec.entity.find('moqui.adk.AdkKnowledgeDoc').condition('ownerPartyId', ownerPartyId)
                    .condition('sourceType', 'upload').condition('sourceId', sourceId).one()
                if (existing != null) {
                    msg = runDoc('AdkKnowledgeServices.update#AdkKnowledge', [adkKnowledgeDocId: existing.adkKnowledgeDocId,
                        ownerPartyId: ownerPartyId, title: title, text: text])
                    if (!msg) updated++
                } else {
                    msg = runDoc('AdkKnowledgeServices.ingest#AdkKnowledge', [ownerPartyId: ownerPartyId,
                        title: title, text: text, sourceType: 'upload', sourceId: sourceId,
                        mimeType: mimeTypes[f.ext] ?: 'text/plain', createdByUserId: ec.user.userId,
                        metadataJson: JsonOutput.toJson([zip: fileName, path: path, folder: folder])])
                    if (!msg) created++
                }
            }
            if (msg && isFatal(msg)) { fatal = msg; break }
            if (msg) skipped.add([path: f.path, reason: msg])
            processed++
            progress([:])
        }
    }
} catch (Exception e) {
    // e.g. a damaged zip: end the job instead of leaving it RUNNING
    ec.logger.warn("Knowledge load ${adkKnowledgeImportId} failed", e)
    ec.message.clearErrors()
    fatal = "Load failed: ${e.message}".toString()
}
progress([status: fatal ? 'ERROR' : 'DONE', errorMessage: fatal,
          completedDate: ec.user.nowTimestamp, clearZipData: true])
ec.logger.info("Knowledge load ${adkKnowledgeImportId} (${job.jobType}, owner ${ownerPartyId}): " +
    "${created} created, ${updated} updated, ${skipped.size()} skipped${fatal ? ', stopped: ' + fatal : ''}")

def aiUtil = ec.resource.script("component://growerp/service/GeminiAiUtil.groovy", null)
try {
    text = aiUtil.callLlmApi(ec, prompt,
        [ownerPartyId: ownerPartyId, apiKey: apiKey, model: model, maxOutputTokens: 2048])
} catch (Exception e) {
    ec.message.addError("Text generation failed: ${e.message}")
}

                def sb = new StringBuilder()
                events.each { e -> if (e.eventJson) sb.append(e.eventJson as String).append('\n') }
                String transcript = sb.toString()
                if (transcript.length() > 12000) transcript = transcript.substring(transcript.length() - 12000)
                prompt = """You maintain a concise running memory about a user and their company for an ERP assistant.
Existing memory (may be empty):
${mem?.summaryText ?: '(none)'}

New conversation events (raw JSON, newest last):
${transcript}

Update the memory: output 4-8 short bullet points capturing durable facts and preferences worth
remembering for future conversations (names, roles, recurring requests, stated preferences,
ongoing tasks). Exclude one-off chit-chat and anything secret (keys, tokens). Output only the bullets."""
